  ('6466b95c-5236-41fb-96f6-ee8a086d78a9', '6335c2b2-e835-4119-b1d4-f67868c432df', '874259d3-0f0a-4ef0-acc8-533d5b02d0e2', 'Numbers to 20', 'Teen numbers are one ten and some ones.', 'I can read and count numbers from 11 to 20.', 1, 6, 2, true),
  ('6053143c-ae0e-46dd-9e21-bd3ebcc98f37', '6335c2b2-e835-4119-b1d4-f67868c432df', '874259d3-0f0a-4ef0-acc8-533d5b02d0e2', 'Counting on and back', 'Count forwards and backwards on a number line.', 'I can count on and count back from any number to 20.', 2, 6, 3, true),
  ('fc8aee44-02c6-402f-a98f-8b0ebfb8b981', '6335c2b2-e835-4119-b1d4-f67868c432df', '7aea290e-55e8-466b-8cab-2b2426cd76d1', 'More or fewer', 'Compare two groups to find which has more.', 'I can tell which group has more and which has fewer.', 1, 5, 4, true),
  ('408e95f1-7968-453a-9794-7e1b52677f44', '6335c2b2-e835-4119-b1d4-f67868c432df', '7aea290e-55e8-466b-8cab-2b2426cd76d1', 'Greater than, less than', 'Use <, > and = with numbers to 50.', 'I can use <, > and = to compare numbers.', 2, 6, 5, true),
