  ('4fc0c1b3-fe5d-4faa-9218-6c29d9e76f88', 'dc9b91ec-7788-48e5-bb83-0d6a0392d583', 'd3c30eae-92d4-4f1d-9616-18dc47b95b7b', 'Adding with objects', 'Put two groups together and count them all.', 'I can add two groups to find how many altogether.', 1, 5, 1, true),
  ('2ec58d61-ed6e-4d1a-b8b2-f957ef92b988', 'dc9b91ec-7788-48e5-bb83-0d6a0392d583', 'd3c30eae-92d4-4f1d-9616-18dc47b95b7b', 'Add on a number line', 'Jump forward on a number line to add.', 'I can add numbers to 20 using a number line.', 2, 6, 2, true),
  ('716be184-5ca4-403d-ba9b-d31eb16bdc47', 'dc9b91ec-7788-48e5-bb83-0d6a0392d583', 'd3c30eae-92d4-4f1d-9616-18dc47b95b7b', 'Missing numbers', 'Find the number that makes an addition true.', 'I can find a missing number in an addition.', 3, 7, 3, true),
  ('565b7100-bb4d-4b0b-972e-db26e0380799', 'dc9b91ec-7788-48e5-bb83-0d6a0392d583', '5e571634-d6d8-441d-b466-29fe39980c47', 'Taking away', 'Take some away and count what is left.', 'I can take away to find how many are left.', 1, 5, 4, true),
