  ('cdf411b2-d840-4c63-95a4-f150f50b9571', 'dc9b91ec-7788-48e5-bb83-0d6a0392d583', '5e571634-d6d8-441d-b466-29fe39980c47', 'Number stories', 'Decide whether to add or subtract in a story.', 'I can choose to add or subtract to solve a story problem.', 3, 7, 6, true),
  ('3f3c3d29-ae1f-4416-bf29-d4034d6cfae0', 'dcc7c424-6870-40c5-8728-692e05532f0f', 'de4c4772-cf46-4127-bfc4-943022a5eb05', 'Name the shape', 'Know circles, triangles, squares and more.', 'I can name common 2D shapes and count their sides.', 1, 5, 1, true),
  ('27400d50-b0da-48c1-8cbb-a6ae0dd8ff5f', 'dcc7c424-6870-40c5-8728-692e05532f0f', 'de4c4772-cf46-4127-bfc4-943022a5eb05', 'Patterns', 'Continue shape and number patterns.', 'I can find what comes next in a pattern.', 2, 6, 2, true),
  ('4d838ba2-d971-4609-8241-af6815c99ebf', 'dcc7c424-6870-40c5-8728-692e05532f0f', 'de4c4772-cf46-4127-bfc4-943022a5eb05', 'Measuring length', 'Use a ruler to measure in centimetres.', 'I can measure and compare lengths in centimetres.', 2, 6, 3, true),
