  ('7a740449-3406-49aa-ad95-056bbbd042b4', '36807931-54be-4146-983f-dbc3c861e1a8', 'f9f21cc0-fb06-4319-ace0-42a6333593ef', 'What is a digit worth?', 'Find the value of each digit up to thousands.', 'I can say the value of any digit in a 4-digit number.', 2, 6, 2, true),
  ('dbdef370-8ba4-4321-9569-a27ae1e28923', '36807931-54be-4146-983f-dbc3c861e1a8', 'f9f21cc0-fb06-4319-ace0-42a6333593ef', 'Rounding', 'Round to the nearest 10 and 100.', 'I can round numbers to the nearest 10 or 100.', 3, 7, 3, true),
  ('ca0a26ea-52fd-4fc3-9d54-ef6cce146a1d', '36807931-54be-4146-983f-dbc3c861e1a8', 'cd2b3b33-e26d-4530-8a0c-3251e1089e7e', 'Equal groups and arrays', 'See multiplication as rows of equal size.', 'I can use arrays to multiply.', 1, 6, 4, true),
  ('f38d59d0-1246-4c79-ac8c-e042171c4c93', '36807931-54be-4146-983f-dbc3c861e1a8', 'cd2b3b33-e26d-4530-8a0c-3251e1089e7e', 'Times tables', 'Practise times tables up to 12 × 12.', 'I can recall multiplication facts.', 2, 7, 5, true),
  ('bc10714a-1f18-451b-9df2-26e4643fb37d', '36807931-54be-4146-983f-dbc3c861e1a8', 'cd2b3b33-e26d-4530-8a0c-3251e1089e7e', 'Multiplication word problems', 'Spot equal groups in stories.', 'I can solve word problems using multiplication.', 3, 7, 6, true),
  ('8bc01bec-fd00-45af-bc00-45ce640f51a1', '0a7a6b88-cff2-460d-a3fa-ac2e658a94a3', '88aea126-fc96-4fa5-9b86-86a01ff45257', 'Sharing equally', 'Share things fairly between groups.', 'I can share equally and write it as division.', 1, 6, 1, true),
  ('ec33dba1-363b-4d64-8fde-59db59a9a286', '0a7a6b88-cff2-460d-a3fa-ac2e658a94a3', '88aea126-fc96-4fa5-9b86-86a01ff45257', 'Division facts', 'Use times tables to divide.', 'I can use multiplication facts to divide.', 2, 7, 2, true),
  ('e4f8c15f-f842-4302-a023-8c35cd602b50', '0a7a6b88-cff2-460d-a3fa-ac2e658a94a3', '88aea126-fc96-4fa5-9b86-86a01ff45257', 'Division word problems', 'Solve sharing and grouping stories, with remainders.', 'I can solve division word problems, including ones with remainders.', 3, 8, 3, true),
  ('93be7b9a-dedb-460b-8ff6-9458942c9d99', '0a7a6b88-cff2-460d-a3fa-ac2e658a94a3', 'a8925bd0-a9a5-4059-a5ec-4c4e3e1183df', 'Parts of a whole', 'Name fractions from shaded shapes.', 'I can name the fraction of a shape that is shaded.', 1, 6, 4, true),
  ('25358f2e-7580-4cd3-b3c3-0e24d65947f1', '0a7a6b88-cff2-460d-a3fa-ac2e658a94a3', 'a8925bd0-a9a5-4059-a5ec-4c4e3e1183df', 'Fractions of amounts', 'Find a fraction of a number by dividing.', 'I can find a fraction of an amount.', 2, 7, 5, true),
  ('099f9d3d-977c-42fe-9b24-92d3fc1f8c3c', '0a7a6b88-cff2-460d-a3fa-ac2e658a94a3', 'a8925bd0-a9a5-4059-a5ec-4c4e3e1183df', 'Comparing fractions', 'Decide which fraction is bigger.', 'I can compare fractions with the same top or bottom number.', 3, 7, 6, true),
  ('d0f19b69-e5c7-45e4-adfb-245f51276442', '8d577cb0-c366-47b1-8c3a-f01a5e6fe003', '30449cbc-fce1-4f01-a0de-33d62b45dd53', 'Telling the time', 'Read o''clock, half past, quarter times and 5-minute times.', 'I can read the time on an analogue clock.', 1, 7, 1, true),
  ('183b9378-9415-41c5-adaf-645244f6d4ef', '8d577cb0-c366-47b1-8c3a-f01a5e6fe003', '30449cbc-fce1-4f01-a0de-33d62b45dd53', 'Counting money', 'Add coins and work out change.', 'I can count coins and find change.', 2, 7, 2, true),
  ('872d05b9-9741-4586-b823-475f1a6e7144', '8d577cb0-c366-47b1-8c3a-f01a5e6fe003', '30449cbc-fce1-4f01-a0de-33d62b45dd53', 'Shapes and angles', 'Sides, corners, right angles and perimeter.', 'I can describe shapes and find the perimeter of rectangles.', 2, 7, 3, true),
  ('af7fec15-39a0-4d96-a5cf-d61bbdfbaf0c', '4d356a8b-10ed-4102-8e65-25e50d1d2574', '9f308b1e-9bb2-48f9-acd4-e1d041806b83', 'Fractions and decimals', 'Switch between fractions and decimals.', 'I can write fractions as decimals and decimals as fractions.', 1, 7, 1, true),
  ('d32b6072-1037-41bf-a34f-67d87b8c1f75', '4d356a8b-10ed-4102-8e65-25e50d1d2574', '9f308b1e-9bb2-48f9-acd4-e1d041806b83', 'Adding fractions', 'Add fractions with the same or related denominators.', 'I can add fractions by making the denominators the same.', 2, 8, 2, true),
  ('2c007681-ba89-4b7c-a776-b5c7776dd8ea', '4d356a8b-10ed-4102-8e65-25e50d1d2574', '9f308b1e-9bb2-48f9-acd4-e1d041806b83', 'Calculating with decimals', 'Add, subtract, and multiply or divide by 10 and 100.', 'I can add and subtract decimals and multiply or divide them by 10 and 100.', 3, 8, 3, true),
  ('b9edd62a-4e92-41ad-aac1-f5400c17ed3b', '4d356a8b-10ed-4102-8e65-25e50d1d2574', 'edb4ec1c-1a07-42b7-a3c7-2e2e57389ec1', 'What is a percentage?', 'Percent means "out of 100".', 'I can understand percentages as parts of 100.', 1, 6, 4, true),
  ('498ca0eb-c600-4ae8-8c1f-e1a16a46adfe', '4d356a8b-10ed-4102-8e65-25e50d1d2574', 'edb4ec1c-1a07-42b7-a3c7-2e2e57389ec1', 'Percentages of amounts', 'Find 10%, 25%, 50% and more of a number.', 'I can find a percentage of an amount.', 2, 7, 5, true),
  ('014c4da5-d493-4074-96de-b39782b99fd6', '4d356a8b-10ed-4102-8e65-25e50d1d2574', 'edb4ec1c-1a07-42b7-a3c7-2e2e57389ec1', 'Ratios', 'Simplify ratios and share in a ratio.', 'I can simplify a ratio and share an amount in a given ratio.', 3, 8, 6, true),
  ('e922268c-0682-478b-9d81-68ae70200c8d', '349cfa46-3361-41b9-9363-d55811932af3', '27e47ed0-dcb8-4f5f-9708-354eab2063cd', 'Below zero', 'Place and compare negative numbers.', 'I can order and compare negative numbers.', 1, 6, 1, true),
  ('c7b1bd5e-f206-4953-afd2-8a840eb9c009', '349cfa46-3361-41b9-9363-d55811932af3', '27e47ed0-dcb8-4f5f-9708-354eab2063cd', 'Adding and subtracting negatives', 'Move along the number line across zero.', 'I can add and subtract with negative numbers.', 2, 8, 2, true),
  ('684bf745-e1dd-47ae-9dd8-a6f712cb4d48', '349cfa46-3361-41b9-9363-d55811932af3', '27e47ed0-dcb8-4f5f-9708-354eab2063cd', 'Temperature problems', 'Solve real problems with temperatures below zero.', 'I can solve word problems involving negative numbers.', 3, 8, 3, true),
  ('f60ed9e4-4a14-412f-861e-d27eb1b3f6a9', '95b4708c-510b-4e73-8517-245e834662dd', '7bc79dc7-9fea-4524-a7ad-34c5ae012802', 'Perimeter', 'Find the distance around rectangles and squares.', 'I can calculate the perimeter of rectangles and squares.', 1, 6, 1, true),
  ('111e6d59-4819-412a-8d07-1f638046fd2c', '95b4708c-510b-4e73-8517-245e834662dd', '7bc79dc7-9fea-4524-a7ad-34c5ae012802', 'Area of rectangles', 'Count squares, then multiply length by width.', 'I can calculate the area of a rectangle.', 2, 7, 2, true),
  ('8744379c-ed0a-436d-bfb0-dfce89ad5c57', '95b4708c-510b-4e73-8517-245e834662dd', '7bc79dc7-9fea-4524-a7ad-34c5ae012802', 'Area of triangles', 'A triangle is half a rectangle.', 'I can calculate the area of a triangle.', 3, 8, 3, true),
  ('327c2d58-9405-4fbf-aada-190aa131e319', '349cfa46-3361-41b9-9363-d55811932af3', '43bb5e40-227c-4861-9891-3fa243f34733', 'Letters for numbers', 'Substitute values into expressions.', 'I can work out the value of an expression when I know the letter.', 1, 7, 4, true),
  ('ee175789-43e1-4c82-918a-4b0346c8d77c', '349cfa46-3361-41b9-9363-d55811932af3', '43bb5e40-227c-4861-9891-3fa243f34733', 'Solving equations', 'Find the unknown by doing the opposite operation.', 'I can solve one-step and two-step equations.', 2, 8, 5, true),
  ('a71c0567-02dd-4d66-8368-3db11a369328', '349cfa46-3361-41b9-9363-d55811932af3', '43bb5e40-227c-4861-9891-3fa243f34733', 'Multi-step problems', 'Break bigger problems into steps.', 'I can solve word problems that need more than one step.', 3, 9, 6, true)
insert into public.lesson_sections (id, lesson_id, section_type, title, content_json, display_order) values
  ('3284c3ef-da35-43b6-9b9a-50ed5aba685c', 'dc34b71a-d6e5-4a61-9ecb-9ec077dc9567', 'introduction', 'Let''s learn', '{"kind":"introduction","text":"Counting tells us how many. Touch each thing once and say one number for it.","visual":{"kind":"objects","object":"apple","groups":[5]}}'::jsonb, 1),
  ('3184c25c-db35-4549-9a9a-4f5a5bba69ef', 'dc34b71a-d6e5-4a61-9ecb-9ec077dc9567', 'worked_example', 'Worked example', '{"kind":"worked_example","problem":"How many stars are there?","steps":["Point to the first star and say 1.","Keep going: 2, 3, 4.","The last number you say is how many: 4 stars."],"visual":{"kind":"objects","object":"star","groups":[4]}}'::jsonb, 2),
  ('3484c715-d835-4090-999a-4dc75cba6b82', 'dc34b71a-d6e5-4a61-9ecb-9ec077dc9567', 'practice', 'Your turn', '{"kind":"practice","text":"Try 5 questions. You get two tries at each one."}'::jsonb, 3),
  ('3384c582-d935-4223-989a-4c345dba6d15', 'dc34b71a-d6e5-4a61-9ecb-9ec077dc9567', 'summary', 'Remember', '{"kind":"summary","points":["Count each thing once.","The last number you say tells you how many."]}'::jsonb, 4),
  ('2b1c51b5-68de-49ec-9f0e-0f937dbafc22', '6466b95c-5236-41fb-96f6-ee8a086d78a9', 'introduction', 'Let''s learn', '{"kind":"introduction","text":"Numbers from 11 to 19 are 1 ten and some ones. 20 is 2 tens.","visual":{"kind":"objects","object":"block","groups":[10,3]}}'::jsonb, 1),
