  ('6dc527b2-1cb5-4f4f-9d58-3b5cedf0c371', '1fa81736-0a83-4d8b-8c29-a94c0dbfaa51', 'numeric', 'What number is 4 hundreds, 0 tens and 7 ones?', null, '{"value":"407"}'::jsonb, null, '4 hundreds is 400, 0 tens is 0 and 7 ones is 7. 400 + 0 + 7 = 407. The 0 keeps the tens place empty.', 'Write a 0 for the empty tens place.', 1, 10, 3, true),
  ('6ec52945-1bb5-4dbc-9e58-3cefecf0c1de', '1fa81736-0a83-4d8b-8c29-a94c0dbfaa51', 'visual_quantity', 'What number do the blocks show?', '{"kind":"base_ten","hundreds":7,"tens":6,"ones":8}'::jsonb, '{"value":"768"}'::jsonb, '[{"id":"778","label":"778"},{"id":"786","label":"786"},{"id":"668","label":"668"},{"id":"768","label":"768"}]'::jsonb, '7 hundreds = 700, 6 tens = 60 and 8 ones = 8. 700 + 60 + 8 = 768.', 'Count the hundreds, then the tens, then the ones.', 1, 10, 4, true),
