  ('1a650878-1e65-487f-ac62-82f21ee33f99', '7a740449-3406-49aa-ad95-056bbbd042b4', 'multiple_choice', 'What is the value of the digit 7 in 5,278?', null, '{"value":"c"}'::jsonb, '[{"id":"a","label":"700"},{"id":"b","label":"7,000"},{"id":"c","label":"70"},{"id":"d","label":"7"}]'::jsonb, 'The 7 is in the tens place, so it is worth 7 tens: 70.', 'Name each place from the right: ones, tens, hundreds, thousands.', 2, 10, 2, true),
  ('1d650d31-1f65-4a12-ab62-815f1be33ae0', '7a740449-3406-49aa-ad95-056bbbd042b4', 'multiple_choice', 'Which number has a 6 in the tens place?', null, '{"value":"b"}'::jsonb, '[{"id":"a","label":"634"},{"id":"b","label":"365"},{"id":"c","label":"456"},{"id":"d","label":"6,012"}]'::jsonb, 'In 365 the digits are 3 hundreds, 6 tens and 5 ones, so 365 has 6 in the tens place. In 634 the 6 is hundreds, in 456 it is ones and in 6,012 it is thousands.', 'The tens place is second from the right.', 2, 10, 3, true),
  ('1c650b9e-2065-4ba5-aa62-7fcc1ce33c73', '7a740449-3406-49aa-ad95-056bbbd042b4', 'multiple_choice', 'What is the value of the digit 7 in 5,617?', null, '{"value":"b"}'::jsonb, '[{"id":"a","label":"700"},{"id":"b","label":"7"},{"id":"c","label":"70"},{"id":"d","label":"7,000"}]'::jsonb, 'The 7 is in the ones place, so it is worth 7 ones: 7.', 'Name each place from the right: ones, tens, hundreds, thousands.', 2, 10, 4, true),
  ('1f651057-1965-40a0-a962-7e3921e34452', '7a740449-3406-49aa-ad95-056bbbd042b4', 'compare', 'Which sign makes this true?', '{"kind":"compare","left":"134","right":"330"}'::jsonb, '{"value":"<"}'::jsonb, null, 'Compare the tens first: 33 tens is more than 13 tens. So 134 < 330. The open side of the sign faces the bigger number.', 'Which number is bigger? The open side of < or > faces the bigger number.', 2, 10, 5, true),
  ('0841f89a-b534-4f67-bdc0-9d8439165319', 'dbdef370-8ba4-4321-9569-a27ae1e28923', 'numeric', 'Round 33 to the nearest 10.', '{"kind":"number_line","min":30,"max":40,"step":1,"highlight":[33]}'::jsonb, '{"value":"30"}'::jsonb, null, '33 is between 30 and 40. The ones digit is 3, which is less than 5, so round down to 30.', 'Look at the ones digit. Is it 5 or more?', 3, 10, 1, true),
  ('0941fa2d-b434-4dd4-bec0-9f1738165186', 'dbdef370-8ba4-4321-9569-a27ae1e28923', 'numeric', 'Round 65 to the nearest 10.', '{"kind":"number_line","min":60,"max":70,"step":1,"highlight":[65]}'::jsonb, '{"value":"70"}'::jsonb, null, '65 is between 60 and 70. The ones digit is 5, which is 5 or more, so round up to 70.', 'Look at the ones digit. Is it 5 or more?', 3, 10, 2, true),
  ('0641f574-b734-428d-bfc0-a0aa37164ff3', 'dbdef370-8ba4-4321-9569-a27ae1e28923', 'numeric', 'Round 274 to the nearest 100.', '{"kind":"number_line","min":200,"max":300,"step":10,"highlight":[274]}'::jsonb, '{"value":"300"}'::jsonb, null, '274 is between 200 and 300. The tens digit is 7, which is 5 or more, so round up to 300.', 'Look at the tens digit. Is it 5 or more?', 3, 10, 3, true),
