  ('f2258610-3a18-4f55-b252-697ae979e347', 'ca0a26ea-52fd-4fc3-9d54-ef6cce146a1d', 'numeric', 'There are 4 rows with 5 flowers in each row. How many flowers are there?', '{"kind":"array","rows":4,"cols":5,"object":"flower"}'::jsonb, '{"value":"20"}'::jsonb, null, '4 rows of 5 is 4 × 5. Count in 5s: 5, 10, 15, 20. So 4 × 5 = 20.', 'Count in 5s, once for each row.', 1, 10, 1, true),
  ('f32587a3-3918-4dc2-b352-6b0de879e1b4', 'ca0a26ea-52fd-4fc3-9d54-ef6cce146a1d', 'numeric', 'There are 2 rows with 4 blocks in each row. How many blocks are there?', '{"kind":"array","rows":2,"cols":4,"object":"block"}'::jsonb, '{"value":"8"}'::jsonb, null, '2 rows of 4 is 2 × 4. Count in 4s: 4, 8. So 2 × 4 = 8.', 'Count in 4s, once for each row.', 1, 10, 2, true),
  ('f4258936-3818-4c2f-b052-6654eb79e66d', 'ca0a26ea-52fd-4fc3-9d54-ef6cce146a1d', 'numeric', 'What is 4 × 2?', null, '{"value":"8"}'::jsonb, null, '4 × 2 means 4 groups of 2. Count in 2s: 2, 4, 6, 8. So 4 × 2 = 8.', 'Count in 2s, 4 times.', 1, 10, 3, true),
  ('f5258ac9-3718-4a9c-b152-67e7ea79e4da', 'ca0a26ea-52fd-4fc3-9d54-ef6cce146a1d', 'numeric', 'There are 4 rows with 3 apples in each row. How many apples are there?', '{"kind":"array","rows":4,"cols":3,"object":"apple"}'::jsonb, '{"value":"12"}'::jsonb, null, '4 rows of 3 is 4 × 3. Count in 3s: 3, 6, 9, 12. So 4 × 3 = 12.', 'Count in 3s, once for each row.', 1, 10, 4, true),
  ('f6258c5c-3618-4909-ae52-632ee579dcfb', 'ca0a26ea-52fd-4fc3-9d54-ef6cce146a1d', 'numeric', 'What is 2 × 5?', null, '{"value":"10"}'::jsonb, null, '2 × 5 means 2 groups of 5. Count in 5s: 5, 10. So 2 × 5 = 10.', 'Count in 5s, 2 times.', 1, 10, 5, true),
  ('485938ba-92f2-4db7-a7f3-000419ace9c9', 'f38d59d0-1246-4c79-ac8c-e042171c4c93', 'numeric', 'What is 12 × 3?', null, '{"value":"36"}'::jsonb, null, '12 × 3 means 12 groups of 3. Split it up: 5 × 3 = 15 and 7 × 3 = 21. 15 + 21 = 36. So 12 × 3 = 36.', 'Count in 3s, 12 times.', 2, 10, 1, true),
  ('49593a4d-91f2-4c24-a8f3-019718ace836', 'f38d59d0-1246-4c79-ac8c-e042171c4c93', 'numeric', 'What is 10 × 4?', null, '{"value":"40"}'::jsonb, null, '10 × 4 means 10 groups of 4. Split it up: 5 × 4 = 20 and 5 × 4 = 20. 20 + 20 = 40. So 10 × 4 = 40.', 'Count in 4s, 10 times.', 2, 10, 2, true),
  ('46593594-94f2-40dd-a9f3-032a17ace6a3', 'f38d59d0-1246-4c79-ac8c-e042171c4c93', 'missing_number', 'What number goes in the box?', '{"kind":"equation","parts":["5","×",null,"=","30"]}'::jsonb, '{"value":"6"}'::jsonb, null, 'Count in 5s until you reach 30: that takes 6 steps. So 5 × 6 = 30. Check: 30 ÷ 5 = 6.', 'How many 5s make 30?', 2, 10, 3, true),
  ('47593727-93f2-4f4a-aaf3-04bd16ace510', 'f38d59d0-1246-4c79-ac8c-e042171c4c93', 'numeric', 'What is 4 × 8?', null, '{"value":"32"}'::jsonb, null, '4 × 8 means 4 groups of 8. Count in 8s: 8, 16, 24, 32. So 4 × 8 = 32.', 'Count in 8s, 4 times.', 2, 10, 4, true),
  ('4459326e-8ef2-476b-a3f2-f9b81dacf015', 'f38d59d0-1246-4c79-ac8c-e042171c4c93', 'missing_number', 'What number goes in the box?', '{"kind":"equation","parts":["4","×",null,"=","16"]}'::jsonb, '{"value":"4"}'::jsonb, null, 'Count in 4s until you reach 16: that takes 4 steps. So 4 × 4 = 16. Check: 16 ÷ 4 = 4.', 'How many 4s make 16?', 2, 10, 5, true),
  ('ac1cf2b0-3d8a-48cd-bbf7-ff42e83570e7', 'bc10714a-1f18-451b-9df2-26e4643fb37d', 'numeric', 'Omar has 6 tables with 4 chairs in each. How many chairs are there altogether?', null, '{"value":"24"}'::jsonb, null, 'There are 6 equal groups of 4, so multiply: 6 × 4 = 24. There are 24 chairs.', 'Equal groups means you can multiply.', 3, 10, 1, true),
  ('ad1cf443-3c8a-473a-bcf8-00d5e7356f54', 'bc10714a-1f18-451b-9df2-26e4643fb37d', 'numeric', 'Zara has 5 bags with 4 oranges in each. How many oranges are there altogether?', null, '{"value":"20"}'::jsonb, null, 'There are 5 equal groups of 4, so multiply: 5 × 4 = 20. There are 20 oranges.', 'Equal groups means you can multiply.', 3, 10, 2, true),
  ('ae1cf5d6-3b8a-45a7-b9f7-fc1cea35740d', 'bc10714a-1f18-451b-9df2-26e4643fb37d', 'numeric', 'What is 8 × 9?', null, '{"value":"72"}'::jsonb, null, '8 × 9 means 8 groups of 9. Split it up: 5 × 9 = 45 and 3 × 9 = 27. 45 + 27 = 72. So 8 × 9 = 72.', 'Count in 9s, 8 times.', 3, 10, 3, true),
  ('af1cf769-3a8a-4414-baf7-fdafe935727a', 'bc10714a-1f18-451b-9df2-26e4643fb37d', 'numeric', 'Kai has 8 tables with 3 chairs in each. How many chairs are there altogether?', null, '{"value":"24"}'::jsonb, null, 'There are 8 equal groups of 3, so multiply: 8 × 3 = 24. There are 24 chairs.', 'Equal groups means you can multiply.', 3, 10, 4, true),
  ('b01cf8fc-398a-4281-b7f7-f8f6e4356a9b', 'bc10714a-1f18-451b-9df2-26e4643fb37d', 'numeric', 'Noah has 9 bags with 9 oranges in each. How many oranges are there altogether?', null, '{"value":"81"}'::jsonb, null, 'There are 9 equal groups of 9, so multiply: 9 × 9 = 81. There are 81 oranges.', 'Equal groups means you can multiply.', 3, 10, 5, true),
  ('f1e00c06-3aae-4eb9-9924-3cb028844a2b', '8bc01bec-fd00-45af-bc00-45ce640f51a1', 'numeric', 'Share 12 shells equally between 3 friends. How many does each friend get?', '{"kind":"objects","object":"shell","groups":[12]}'::jsonb, '{"value":"4"}'::jsonb, null, 'Give one to each friend in turn until they are all gone. 12 ÷ 3 = 4, because 3 × 4 = 12.', 'Which number times 3 makes 12?', 1, 10, 1, true),
  ('f2e00d99-39ae-4d26-9a24-3e4327844898', '8bc01bec-fd00-45af-bc00-45ce640f51a1', 'numeric', 'Share 20 cookies equally between 4 friends. How many does each friend get?', '{"kind":"objects","object":"cookie","groups":[20]}'::jsonb, '{"value":"5"}'::jsonb, null, 'Give one to each friend in turn until they are all gone. 20 ÷ 4 = 5, because 4 × 5 = 20.', 'Which number times 4 makes 20?', 1, 10, 2, true),
  ('efe008e0-38ae-4b93-9b24-3fd62a844d51', '8bc01bec-fd00-45af-bc00-45ce640f51a1', 'numeric', 'What is 4 ÷ 2?', null, '{"value":"2"}'::jsonb, null, 'Think of the times table: 2 × 2 = 4. So 4 ÷ 2 = 2.', '2 times what makes 4?', 1, 10, 3, true),
  ('f0e00a73-37ae-4a00-9c24-416929844bbe', '8bc01bec-fd00-45af-bc00-45ce640f51a1', 'numeric', 'Share 12 apples equally between 4 friends. How many does each friend get?', '{"kind":"objects","object":"apple","groups":[12]}'::jsonb, '{"value":"3"}'::jsonb, null, 'Give one to each friend in turn until they are all gone. 12 ÷ 4 = 3, because 4 × 3 = 12.', 'Which number times 4 makes 12?', 1, 10, 4, true),
  ('f5e01252-3eae-4505-9d24-42fc2c845077', '8bc01bec-fd00-45af-bc00-45ce640f51a1', 'numeric', 'What is 30 ÷ 5?', null, '{"value":"6"}'::jsonb, null, 'Think of the times table: 5 × 6 = 30. So 30 ÷ 5 = 6.', '5 times what makes 30?', 1, 10, 5, true),
  ('42661a73-ffe9-415a-8139-42d5bfa68074', 'ec33dba1-363b-4d64-8fde-59db59a9a286', 'numeric', 'What is 10 ÷ 5?', null, '{"value":"2"}'::jsonb, null, 'Think of the times table: 5 × 2 = 10. So 10 ÷ 5 = 2.', '5 times what makes 10?', 2, 10, 1, true),
  ('416618e0-00e9-42ed-8039-4142c0a68207', 'ec33dba1-363b-4d64-8fde-59db59a9a286', 'numeric', 'What is 27 ÷ 9?', null, '{"value":"3"}'::jsonb, null, 'Think of the times table: 9 × 3 = 27. So 27 ÷ 9 = 3.', '9 times what makes 27?', 2, 10, 2, true),
  ('44661d99-fde9-4e34-bf39-3fafc1a6839a', 'ec33dba1-363b-4d64-8fde-59db59a9a286', 'missing_number', 'What number goes in the box?', '{"kind":"equation","parts":["80","÷",null,"=","8"]}'::jsonb, '{"value":"10"}'::jsonb, null, '80 split into groups of the missing number makes 8. Since 8 × 10 = 80, the missing number is 10.', 'Think: 8 × what = 80?', 2, 10, 3, true),
  ('43661c06-fee9-4fc7-be39-3e1cc2a6852d', 'ec33dba1-363b-4d64-8fde-59db59a9a286', 'missing_number', 'What number goes in the box?', '{"kind":"equation","parts":["16","÷",null,"=","4"]}'::jsonb, '{"value":"4"}'::jsonb, null, '16 split into groups of the missing number makes 4. Since 4 × 4 = 16, the missing number is 4.', 'Think: 4 × what = 16?', 2, 10, 4, true),
  ('466620bf-fbe9-4b0e-bd39-3c89bba67a28', 'ec33dba1-363b-4d64-8fde-59db59a9a286', 'numeric', 'What is 45 ÷ 9?', null, '{"value":"5"}'::jsonb, null, 'Think of the times table: 9 × 5 = 45. So 45 ÷ 9 = 5.', '9 times what makes 45?', 2, 10, 5, true),
  ('a318a4ed-1029-4eac-9ab6-685b087867f2', 'e4f8c15f-f842-4302-a023-8c35cd602b50', 'numeric', 'Kai puts 30 books onto 6 shelves, with the same number on each shelf. How many books go on each shelf?', null, '{"value":"5"}'::jsonb, null, 'Sharing equally means divide: 30 ÷ 6 = 5, because 6 × 5 = 30.', 'Sharing equally means dividing.', 3, 10, 1, true),
  ('a218a35a-1129-403f-99b6-66c809786985', 'e4f8c15f-f842-4302-a023-8c35cd602b50', 'numeric', '16 children make teams of 3. How many full teams can they make?', null, '{"value":"5"}'::jsonb, null, '16 ÷ 3 = 5 remainder 1, because 3 × 5 = 15 and 16 − 15 = 1. So there are 5 full teams and 1 child left over.', 'Count in 3s without going past 16.', 3, 10, 2, true),
  ('a118a1c7-1229-41d2-9cb6-6b81067864cc', 'e4f8c15f-f842-4302-a023-8c35cd602b50', 'numeric', 'Ava puts 18 books onto 6 shelves, with the same number on each shelf. How many books go on each shelf?', null, '{"value":"3"}'::jsonb, null, 'Sharing equally means divide: 18 ÷ 6 = 3, because 6 × 3 = 18.', 'Sharing equally means dividing.', 3, 10, 3, true),
  ('a018a034-1329-4365-9bb6-69ee0778665f', 'e4f8c15f-f842-4302-a023-8c35cd602b50', 'numeric', '20 children make teams of 3. How many full teams can they make?', null, '{"value":"6"}'::jsonb, null, '20 ÷ 3 = 6 remainder 2, because 3 × 6 = 18 and 20 − 18 = 2. So there are 6 full teams and 2 children left over.', 'Count in 3s without going past 20.', 3, 10, 4, true),
