  ('23c1a460-547a-4ed5-b425-146ec7301133', '93be7b9a-dedb-460b-8ff6-9458942c9d99', 'multiple_choice', 'What fraction of the bar is shaded?', '{"kind":"fraction_bar","parts":3,"shaded":2}'::jsonb, '{"value":"a"}'::jsonb, '[{"id":"a","label":"2/3"},{"id":"b","label":"1/3"},{"id":"c","label":"2/4"},{"id":"d","label":"2/1"}]'::jsonb, 'The bar has 3 equal parts and 2 are shaded. The bottom number is the total parts, the top number is the shaded parts: 2/3.', 'Count all the parts, then count the shaded parts.', 1, 10, 1, true),
  ('24c1a5f3-537a-4d42-b525-1601c6300fa0', '93be7b9a-dedb-460b-8ff6-9458942c9d99', 'multiple_choice', 'What fraction of the bar is shaded?', '{"kind":"fraction_bar","parts":5,"shaded":1}'::jsonb, '{"value":"a"}'::jsonb, '[{"id":"a","label":"1/5"},{"id":"b","label":"1/4"},{"id":"c","label":"4/5"},{"id":"d","label":"1/6"}]'::jsonb, 'The bar has 5 equal parts and 1 is shaded. The bottom number is the total parts, the top number is the shaded parts: 1/5.', 'Count all the parts, then count the shaded parts.', 1, 10, 2, true),
  ('25c1a786-527a-4baf-b225-1148c9301459', '93be7b9a-dedb-460b-8ff6-9458942c9d99', 'multiple_choice', 'Which fraction means one half?', null, '{"value":"c"}'::jsonb, '[{"id":"a","label":"2/1"},{"id":"b","label":"1/3"},{"id":"c","label":"1/2"},{"id":"d","label":"2/2"}]'::jsonb, 'One half means 1 out of 2 equal parts, which we write as 1/2. 2/2 is a whole, and 1/3 is one third.', 'How many equal parts make halves?', 1, 10, 3, true),
  ('26c1a919-517a-4a1c-b325-12dbc83012c6', '93be7b9a-dedb-460b-8ff6-9458942c9d99', 'multiple_choice', 'What fraction of the bar is shaded?', '{"kind":"fraction_bar","parts":6,"shaded":4}'::jsonb, '{"value":"c"}'::jsonb, '[{"id":"a","label":"4/7"},{"id":"b","label":"2/6"},{"id":"c","label":"4/6"},{"id":"d","label":"4/2"}]'::jsonb, 'The bar has 6 equal parts and 4 are shaded. The bottom number is the total parts, the top number is the shaded parts: 4/6.', 'Count all the parts, then count the shaded parts.', 1, 10, 4, true),
  ('27c1aaac-507a-4889-b825-1abacb30177f', '93be7b9a-dedb-460b-8ff6-9458942c9d99', 'multiple_choice', 'What fraction of the bar is shaded?', '{"kind":"fraction_bar","parts":3,"shaded":2}'::jsonb, '{"value":"a"}'::jsonb, '[{"id":"a","label":"2/3"},{"id":"b","label":"1/3"},{"id":"c","label":"2/1"},{"id":"d","label":"3/2"}]'::jsonb, 'The bar has 3 equal parts and 2 are shaded. The bottom number is the total parts, the top number is the shaded parts: 2/3.', 'Count all the parts, then count the shaded parts.', 1, 10, 5, true),
  ('41c4da34-6b12-48e5-8fd8-10e248179b5b', '25358f2e-7580-4cd3-b3c3-0e24d65947f1', 'numeric', 'What is 1/4 of 20?', null, '{"value":"5"}'::jsonb, null, 'Split 20 into 4 equal groups: 20 ÷ 4 = 5. So 1/4 of 20 is 5.', 'Start by dividing 20 by 4.', 2, 10, 1, true),
  ('42c4dbc7-6a12-4752-90d8-1275471799c8', '25358f2e-7580-4cd3-b3c3-0e24d65947f1', 'numeric', 'What is 1/3 of 15?', null, '{"value":"5"}'::jsonb, null, 'Split 15 into 3 equal groups: 15 ÷ 3 = 5. So 1/3 of 15 is 5.', 'Start by dividing 15 by 3.', 2, 10, 2, true),
  ('43c4dd5a-6912-45bf-8dd8-0dbc4a179e81', '25358f2e-7580-4cd3-b3c3-0e24d65947f1', 'numeric', 'What is 1/3 of 18?', null, '{"value":"6"}'::jsonb, null, 'Split 18 into 3 equal groups: 18 ÷ 3 = 6. So 1/3 of 18 is 6.', 'Start by dividing 18 by 3.', 2, 10, 3, true),
  ('44c4deed-6812-442c-8ed8-0f4f49179cee', '25358f2e-7580-4cd3-b3c3-0e24d65947f1', 'numeric', 'What is 1/3 of 9?', null, '{"value":"3"}'::jsonb, null, 'Split 9 into 3 equal groups: 9 ÷ 3 = 3. So 1/3 of 9 is 3.', 'Start by dividing 9 by 3.', 2, 10, 4, true),
  ('3dc4d3e8-6712-4299-8bd8-0a964c17a1a7', '25358f2e-7580-4cd3-b3c3-0e24d65947f1', 'numeric', 'What is 1/2 of 20?', null, '{"value":"10"}'::jsonb, null, 'Split 20 into 2 equal groups: 20 ÷ 2 = 10. So 1/2 of 20 is 10.', 'Start by dividing 20 by 2.', 2, 10, 5, true),
  ('39bac9bf-74b9-4840-8e47-6f6d1f187fde', '099f9d3d-977c-42fe-9b24-92d3fc1f8c3c', 'compare', 'Which sign makes this true?', '{"kind":"compare","left":"2/7","right":"3/7"}'::jsonb, '{"value":"<"}'::jsonb, null, 'Both fractions have 7 equal parts. 3 parts is more than 2 parts, so 2/7 < 3/7.', 'When the bottom numbers match, compare the top numbers.', 3, 10, 1, true),
  ('38bac82c-75b9-49d3-8d47-6dda20188171', '099f9d3d-977c-42fe-9b24-92d3fc1f8c3c', 'compare', 'Which sign makes this true?', '{"kind":"compare","left":"1/9","right":"1/6"}'::jsonb, '{"value":"<"}'::jsonb, null, 'When a whole is cut into more parts, each part is smaller. 1/9 is smaller than 1/6, so 1/9 < 1/6.', 'Would you rather have 1 slice of a cake cut into 2 or into 8?', 3, 10, 2, true),
  ('3bbacce5-76b9-4b66-8c47-6c471d187cb8', '099f9d3d-977c-42fe-9b24-92d3fc1f8c3c', 'compare', 'Which sign makes this true?', '{"kind":"compare","left":"4/9","right":"5/9"}'::jsonb, '{"value":"<"}'::jsonb, null, 'Both fractions have 9 equal parts. 5 parts is more than 4 parts, so 4/9 < 5/9.', 'When the bottom numbers match, compare the top numbers.', 3, 10, 3, true),
  ('3abacb52-77b9-4cf9-8b47-6ab41e187e4b', '099f9d3d-977c-42fe-9b24-92d3fc1f8c3c', 'compare', 'Which sign makes this true?', '{"kind":"compare","left":"7/8","right":"5/8"}'::jsonb, '{"value":">"}'::jsonb, null, 'Both fractions have 8 equal parts. 7 parts is more than 5 parts, so 7/8 > 5/8.', 'When the bottom numbers match, compare the top numbers.', 3, 10, 4, true),
  ('35bac373-78b9-4e8c-8a47-69212318862a', '099f9d3d-977c-42fe-9b24-92d3fc1f8c3c', 'compare', 'Which sign makes this true?', '{"kind":"compare","left":"1/5","right":"4/5"}'::jsonb, '{"value":"<"}'::jsonb, null, 'Both fractions have 5 equal parts. 4 parts is more than 1 parts, so 1/5 < 4/5.', 'When the bottom numbers match, compare the top numbers.', 3, 10, 5, true),
  ('41a4ac6b-a41c-4e82-a0c6-ffc1bc8f7c00', 'd0f19b69-e5c7-45e4-adfb-245f51276442', 'multiple_choice', 'What time does the clock show?', '{"kind":"clock","hour":11,"minute":0}'::jsonb, '{"value":"d"}'::jsonb, '[{"id":"a","label":"11:30"},{"id":"b","label":"12:55"},{"id":"c","label":"10:00"},{"id":"d","label":"11:00"}]'::jsonb, 'The short hand points to 11, so the hour is 11. The long hand points to 12, which means exactly 11 o''clock. The time is 11:00.', 'Read the short hand for the hour, then the long hand for minutes.', 1, 10, 1, true),
  ('40a4aad8-a51c-4015-9fc6-fe2ebd8f7d93', 'd0f19b69-e5c7-45e4-adfb-245f51276442', 'multiple_choice', 'What time does the clock show?', '{"kind":"clock","hour":2,"minute":0}'::jsonb, '{"value":"c"}'::jsonb, '[{"id":"a","label":"12:10"},{"id":"b","label":"2:30"},{"id":"c","label":"2:00"},{"id":"d","label":"3:00"}]'::jsonb, 'The short hand points to 2, so the hour is 2. The long hand points to 12, which means exactly 2 o''clock. The time is 2:00.', 'Read the short hand for the hour, then the long hand for minutes.', 1, 10, 2, true),
  ('43a4af91-a21c-4b5c-9ec6-fc9bbe8f7f26', 'd0f19b69-e5c7-45e4-adfb-245f51276442', 'multiple_choice', 'What time does the clock show?', '{"kind":"clock","hour":3,"minute":45}'::jsonb, '{"value":"c"}'::jsonb, '[{"id":"a","label":"3:15"},{"id":"b","label":"9:15"},{"id":"c","label":"3:45"},{"id":"d","label":"4:45"}]'::jsonb, 'The short hand is between 3 and 4, so the hour is 3. The long hand points to 9. Each number is 5 minutes, so that is 9 × 5 = 45 minutes. The time is 3:45.', 'Read the short hand for the hour, then the long hand for minutes.', 1, 10, 3, true),
  ('42a4adfe-a31c-4cef-9dc6-fb08bf8f80b9', 'd0f19b69-e5c7-45e4-adfb-245f51276442', 'numeric', 'How many minutes are there in one hour?', null, '{"value":"60"}'::jsonb, null, 'In one hour the long hand goes all the way round the clock. That is 12 numbers × 5 minutes = 60 minutes.', 'Count in 5s all the way round the clock.', 1, 10, 4, true),
  ('45a4b2b7-a01c-4836-a4c7-060dc08f824c', 'd0f19b69-e5c7-45e4-adfb-245f51276442', 'multiple_choice', 'What time does the clock show?', '{"kind":"clock","hour":11,"minute":50}'::jsonb, '{"value":"d"}'::jsonb, '[{"id":"a","label":"11:20"},{"id":"b","label":"10:50"},{"id":"c","label":"12:50"},{"id":"d","label":"11:50"}]'::jsonb, 'The short hand is between 11 and 12, so the hour is 11. The long hand points to 10. Each number is 5 minutes, so that is 10 × 5 = 50 minutes. The time is 11:50.', 'Read the short hand for the hour, then the long hand for minutes.', 1, 10, 5, true),
  ('e1795752-731c-48e3-af99-52e4686076e5', '183b9378-9415-41c5-adaf-645244f6d4ef', 'numeric', 'How many cents are there altogether?', '{"kind":"coins","coins":[10,10,1,1]}'::jsonb, '{"value":"22"}'::jsonb, null, 'Start with the biggest coin and count on: 10, 20, 21, 22. That is 22 cents (22¢).', 'Start with the biggest coin, then count on.', 2, 10, 1, true),
  ('e27958e5-721c-4750-b099-547767607552', '183b9378-9415-41c5-adaf-645244f6d4ef', 'numeric', 'How many cents are there altogether?', '{"kind":"coins","coins":[25,5]}'::jsonb, '{"value":"30"}'::jsonb, null, 'Start with the biggest coin and count on: 25, 30. That is 30 cents (30¢).', 'Start with the biggest coin, then count on.', 2, 10, 2, true),
  ('df79542c-751c-4c09-b199-560a666073bf', '183b9378-9415-41c5-adaf-645244f6d4ef', 'numeric', 'Aisha buys a sticker for 50¢ and pays with 100¢. How many cents of change does Aisha get?', null, '{"value":"50"}'::jsonb, null, 'Change is what is left: 100 − 50 = 50. You can check by counting up from 50 to 100. The change is 50¢.', 'Count up from 50 to 100.', 2, 10, 3, true),
  ('e07955bf-741c-4a76-b299-579d6560722c', '183b9378-9415-41c5-adaf-645244f6d4ef', 'numeric', 'How many cents are there altogether?', '{"kind":"coins","coins":[25,10,10,5,5,1]}'::jsonb, '{"value":"56"}'::jsonb, null, 'Start with the biggest coin and count on: 25, 35, 45, 50, 55, 56. That is 56 cents (56¢).', 'Start with the biggest coin, then count on.', 2, 10, 4, true),
  ('dd795106-771c-4f2f-ab99-4c9864607099', '183b9378-9415-41c5-adaf-645244f6d4ef', 'numeric', 'Leo buys an apple for 25¢ and pays with 50¢. How many cents of change does Leo get?', null, '{"value":"25"}'::jsonb, null, 'Change is what is left: 50 − 25 = 25. You can check by counting up from 25 to 50. The change is 25¢.', 'Count up from 25 to 50.', 2, 10, 5, true),
  ('af45eb9b-9ef5-48e8-812f-9119cfe2dc16', '872d05b9-9741-4586-b823-475f1a6e7144', 'numeric', 'How many right angles does a rectangle have?', '{"kind":"shape","shape":"rectangle"}'::jsonb, '{"value":"4"}'::jsonb, null, 'A right angle is a square corner, like the corner of a page. A rectangle has 4 square corners, so it has 4 right angles.', 'Count the square corners.', 2, 10, 1, true),
  ('ae45ea08-9ff5-4a7b-802f-8f86d0e2dda9', '872d05b9-9741-4586-b823-475f1a6e7144', 'multiple_choice', 'Which shape has exactly 5 sides?', null, '{"value":"b"}'::jsonb, '[{"id":"a","label":"hexagon"},{"id":"b","label":"pentagon"},{"id":"c","label":"square"},{"id":"d","label":"triangle"}]'::jsonb, 'A pentagon has 5 sides ("penta" means five). A hexagon has 6, a square has 4 and a triangle has 3.', 'Think of words that start with "penta".', 2, 10, 2, true),
  ('b145eec1-a0f5-4c0e-bf2f-8df3cde2d8f0', '872d05b9-9741-4586-b823-475f1a6e7144', 'numeric', 'What is the perimeter of a rectangle 2 cm long and 5 cm wide?', '{"kind":"rectangle","width":2,"height":5,"unit":"cm"}'::jsonb, '{"value":"14"}'::jsonb, null, 'Perimeter is the distance all the way around. Add all four sides: 2 + 5 + 2 + 5 = 14 cm. That is the same as 2 × (2 + 5).', 'A rectangle has two long sides and two short sides.', 2, 10, 3, true),
  ('b045ed2e-a1f5-4da1-be2f-8c60cee2da83', '872d05b9-9741-4586-b823-475f1a6e7144', 'numeric', 'A square has sides of 5 cm. What is its perimeter, in cm?', '{"kind":"rectangle","width":5,"height":5,"unit":"cm"}'::jsonb, '{"value":"20"}'::jsonb, null, 'A square has 4 equal sides. 5 + 5 + 5 + 5 = 20, or 4 × 5 = 20. The perimeter is 20 cm.', 'All four sides of a square are the same length.', 2, 10, 4, true),
  ('b345f1e7-a2f5-4f34-852f-9765d3e2e262', '872d05b9-9741-4586-b823-475f1a6e7144', 'numeric', 'What is the perimeter of a rectangle 4 m long and 10 m wide?', '{"kind":"rectangle","width":4,"height":10,"unit":"m"}'::jsonb, '{"value":"28"}'::jsonb, null, 'Perimeter is the distance all the way around. Add all four sides: 4 + 10 + 4 + 10 = 28 m. That is the same as 2 × (4 + 10).', 'A rectangle has two long sides and two short sides.', 2, 10, 5, true),
  ('ed6349c7-9a56-4bb8-86ff-49950e76b49e', 'af7fec15-39a0-4d96-a5cf-d61bbdfbaf0c', 'numeric', 'Write 9/25 as a decimal.', null, '{"value":"0.36","format":"decimal"}'::jsonb, null, 'Make the bottom number 100: multiply top and bottom by 4. 9/25 = 36/100 = 0.36.', 'What do you multiply 25 by to make 100?', 1, 10, 1, true),
  ('ec634834-9b56-4d4b-85ff-48020f76b631', 'af7fec15-39a0-4d96-a5cf-d61bbdfbaf0c', 'numeric', 'Write 0.2 as a fraction in its simplest form.', null, '{"value":"1/5","format":"simplest_fraction"}'::jsonb, null, '0.2 means 2 tenths: 2/10. Divide the top and bottom by 2: 2/10 = 1/5.', 'Write it as tenths first, then simplify.', 1, 10, 2, true),
  ('ef634ced-9c56-4ede-84ff-466f0c76b178', 'af7fec15-39a0-4d96-a5cf-d61bbdfbaf0c', 'numeric', 'Write 1/20 as a decimal.', null, '{"value":"0.05","format":"decimal"}'::jsonb, null, 'Make the bottom number 100: multiply top and bottom by 5. 1/20 = 5/100 = 0.05.', 'What do you multiply 20 by to make 100?', 1, 10, 3, true),
  ('ee634b5a-9d57-4071-83ff-44dc0d76b30b', 'af7fec15-39a0-4d96-a5cf-d61bbdfbaf0c', 'numeric', 'Write 0.5 as a fraction in its simplest form.', null, '{"value":"1/2","format":"simplest_fraction"}'::jsonb, null, '0.5 means 5 tenths: 5/10. Divide the top and bottom by 5: 5/10 = 1/2.', 'Write it as tenths first, then simplify.', 1, 10, 4, true),
  ('e963437b-9e57-4204-82ff-43491276baea', 'af7fec15-39a0-4d96-a5cf-d61bbdfbaf0c', 'numeric', 'Write 1/10 as a decimal.', null, '{"value":"0.1","format":"decimal"}'::jsonb, null, 'Make the bottom number 100: multiply top and bottom by 10. 1/10 = 10/100 = 0.1.', 'What do you multiply 10 by to make 100?', 1, 10, 5, true),
  ('25e5c7e8-3485-4589-ac5c-948e17a0fa1f', 'd32b6072-1037-41bf-a34f-67d87b8c1f75', 'numeric', 'What is 1/6 + 3/6?', null, '{"value":"4/6","format":"fraction"}'::jsonb, null, 'The bottom numbers are the same, so add the tops: 1 + 3 = 4. The answer is 4/6, which simplifies to 2/3.', 'Keep the bottom number. Add the top numbers.', 2, 10, 1, true),
  ('26e5c97b-3385-43f6-ad5c-962116a0f88c', 'd32b6072-1037-41bf-a34f-67d87b8c1f75', 'numeric', 'What is 3/5 + 1/5?', null, '{"value":"4/5","format":"fraction"}'::jsonb, null, 'The bottom numbers are the same, so add the tops: 3 + 1 = 4. The answer is 4/5.', 'Keep the bottom number. Add the top numbers.', 2, 10, 2, true),
  ('27e5cb0e-3285-4263-aa5c-916819a0fd45', 'd32b6072-1037-41bf-a34f-67d87b8c1f75', 'numeric', 'What is 1/3 + 1/6?', null, '{"value":"3/6","format":"fraction"}'::jsonb, null, 'Make the bottom numbers the same. 1/3 = 2/6. Then 2/6 + 1/6 = 3/6 = 1/2.', 'Change 1/3 into a fraction with 6 on the bottom.', 2, 10, 3, true),
  ('28e5cca1-3185-40d0-ab5c-92fb18a0fbb2', 'd32b6072-1037-41bf-a34f-67d87b8c1f75', 'numeric', 'What is 5/12 + 5/12?', null, '{"value":"10/12","format":"fraction"}'::jsonb, null, 'The bottom numbers are the same, so add the tops: 5 + 5 = 10. The answer is 10/12, which simplifies to 5/6.', 'Keep the bottom number. Add the top numbers.', 2, 10, 4, true),
  ('29e5ce34-3885-4bd5-b05c-9ada13a0f3d3', 'd32b6072-1037-41bf-a34f-67d87b8c1f75', 'numeric', 'What is 1/5 + 1/10?', null, '{"value":"3/10","format":"fraction"}'::jsonb, null, 'Make the bottom numbers the same. 1/5 = 2/10. Then 2/10 + 1/10 = 3/10.', 'Change 1/5 into a fraction with 10 on the bottom.', 2, 10, 5, true),
  ('3e8624b3-5278-4762-9892-eb11cf39b498', '2c007681-ba89-4b7c-a776-b5c7776dd8ea', 'numeric', 'What is 6.88 − 3.32?', null, '{"value":"3.56","format":"decimal"}'::jsonb, null, 'Line up the decimal points and subtract each place: 6.88 − 3.32 = 3.56, which is 3.56.', 'Write both numbers with two decimal places, then line up the points.', 3, 10, 1, true),
  ('3d862320-5378-48f5-9792-e97ed039b62b', '2c007681-ba89-4b7c-a776-b5c7776dd8ea', 'numeric', 'What is 6.2 × 100?', null, '{"value":"620","format":"decimal"}'::jsonb, null, 'Multiplying by 100 makes a number 100 times bigger: each digit moves two places to the left. 6.2 × 100 = 620.', 'Move each digit two places to the left.', 3, 10, 2, true),
  ('408627d9-5078-443c-9692-e7ebd139b7be', '2c007681-ba89-4b7c-a776-b5c7776dd8ea', 'numeric', 'What is 5.55 + 1.07?', null, '{"value":"6.62","format":"decimal"}'::jsonb, null, 'Line up the decimal points and add each place: 5.55 + 1.07 = 6.62, which is 6.62.', 'Write both numbers with two decimal places, then line up the points.', 3, 10, 3, true),
  ('3f862646-5178-45cf-9592-e658d239b951', '2c007681-ba89-4b7c-a776-b5c7776dd8ea', 'numeric', 'What is 96 ÷ 100?', null, '{"value":"0.96","format":"decimal"}'::jsonb, null, 'Dividing by 100 makes a number 100 times smaller: each digit moves two places to the right. 96 ÷ 100 = 0.96.', 'Move each digit two places to the right.', 3, 10, 4, true),
  ('42862aff-4e78-4116-9c92-f15dd339bae4', '2c007681-ba89-4b7c-a776-b5c7776dd8ea', 'numeric', 'What is 1.89 − 0.12?', null, '{"value":"1.77","format":"decimal"}'::jsonb, null, 'Line up the decimal points and subtract each place: 1.89 − 0.12 = 1.77, which is 1.77.', 'Write both numbers with two decimal places, then line up the points.', 3, 10, 5, true),
  ('48cb7bf0-bc1d-401b-bf5d-6be60f0eaca1', 'b9edd62a-4e92-41ad-aac1-f5400c17ed3b', 'numeric', 'What percentage of the grid is shaded? Type the number only.', '{"kind":"percent_grid","shaded":31}'::jsonb, '{"value":"31"}'::jsonb, null, 'The grid has 100 squares and 31 are shaded. "Per cent" means "out of 100", so 31 out of 100 is 31%.', 'Each full row has 10 squares.', 1, 10, 1, true),
  ('49cb7d83-bb1d-4e88-805d-6d790e0eab0e', 'b9edd62a-4e92-41ad-aac1-f5400c17ed3b', 'multiple_choice', 'Which fraction is the same as 50%?', null, '{"value":"b"}'::jsonb, '[{"id":"a","label":"1/5"},{"id":"b","label":"1/2"},{"id":"c","label":"1/50"},{"id":"d","label":"5/100"}]'::jsonb, '50% means 50 out of 100, which is 50/100. Divide top and bottom by 50: 50/100 = 1/2.', 'Write 50% as a fraction out of 100, then simplify.', 1, 10, 2, true),
  ('4acb7f16-be1d-4341-bd5d-68c00d0ea97b', 'b9edd62a-4e92-41ad-aac1-f5400c17ed3b', 'numeric', 'What percentage of the grid is shaded? Type the number only.', '{"kind":"percent_grid","shaded":55}'::jsonb, '{"value":"55"}'::jsonb, null, 'The grid has 100 squares and 55 are shaded. "Per cent" means "out of 100", so 55 out of 100 is 55%.', 'Each full row has 10 squares.', 1, 10, 3, true),
  ('4bcb80a9-bd1d-41ae-be5d-6a530c0ea7e8', 'b9edd62a-4e92-41ad-aac1-f5400c17ed3b', 'multiple_choice', 'Which fraction is the same as 25%?', null, '{"value":"a"}'::jsonb, '[{"id":"a","label":"1/4"},{"id":"b","label":"1/25"},{"id":"c","label":"2/5"},{"id":"d","label":"1/2"}]'::jsonb, '25% is 25 out of 100: 25/100. Divide top and bottom by 25: 25/100 = 1/4.', 'How many 25s make 100?', 1, 10, 4, true),
  ('4ccb823c-c01d-4667-835d-7232130eb2ed', 'b9edd62a-4e92-41ad-aac1-f5400c17ed3b', 'numeric', 'What percentage of the grid is shaded? Type the number only.', '{"kind":"percent_grid","shaded":48}'::jsonb, '{"value":"48"}'::jsonb, null, 'The grid has 100 squares and 48 are shaded. "Per cent" means "out of 100", so 48 out of 100 is 48%.', 'Each full row has 10 squares.', 1, 10, 5, true),
  ('f7d2f219-28eb-41e6-be51-d3c76d1e9f1c', '498ca0eb-c600-4ae8-8c1f-e1a16a46adfe', 'numeric', 'What is 20% of 160?', null, '{"value":"32"}'::jsonb, null, 'First find 10%: 160 ÷ 10 = 16. Then 20% is 2 × 16 = 32.', 'Find 10% first by dividing by 10.', 2, 10, 1, true),
  ('f6d2f086-29eb-4379-bd51-d2346e1ea0af', '498ca0eb-c600-4ae8-8c1f-e1a16a46adfe', 'numeric', 'What is 10% of 200?', null, '{"value":"20"}'::jsonb, null, '10% means divide by 10. 200 ÷ 10 = 20.', 'Find 10% first by dividing by 10.', 2, 10, 2, true),
  ('f5d2eef3-26eb-4ec0-8051-d6ed6f1ea242', '498ca0eb-c600-4ae8-8c1f-e1a16a46adfe', 'numeric', 'What is 25% of 120?', null, '{"value":"30"}'::jsonb, null, '25% is one quarter. 120 ÷ 4 = 30.', '25% is the same as one quarter.', 2, 10, 3, true),
  ('f4d2ed60-27eb-4053-bf51-d55a701ea3d5', '498ca0eb-c600-4ae8-8c1f-e1a16a46adfe', 'numeric', 'What is 20% of 180?', null, '{"value":"36"}'::jsonb, null, 'First find 10%: 180 ÷ 10 = 18. Then 20% is 2 × 18 = 36.', 'Find 10% first by dividing by 10.', 2, 10, 4, true),
  ('fbd2f865-2ceb-4832-ba51-cd7b691e98d0', '498ca0eb-c600-4ae8-8c1f-e1a16a46adfe', 'numeric', 'What is 30% of 120?', null, '{"value":"36"}'::jsonb, null, 'First find 10%: 120 ÷ 10 = 12. Then 30% is 3 × 12 = 36.', 'Find 10% first by dividing by 10.', 2, 10, 5, true),
  ('ae513d37-9ce7-46e2-811c-5c799339fce4', '014c4da5-d493-4074-96de-b39782b99fd6', 'multiple_choice', 'What is the ratio of fish to flowers, in its simplest form?', '{"kind":"ratio","a":{"object":"fish","count":12},"b":{"object":"flower","count":15}}'::jsonb, '{"value":"a"}'::jsonb, '[{"id":"a","label":"4 : 5"},{"id":"b","label":"4 : 6"},{"id":"c","label":"5 : 4"},{"id":"d","label":"12 : 27"}]'::jsonb, 'There are 12 fish and 15 flowers, so the ratio is 12 : 15. Divide both numbers by 3: 12 ÷ 3 = 4 and 15 ÷ 3 = 5. The ratio is 4 : 5.', 'Find a number that divides both counts exactly.', 3, 10, 1, true),
  ('ad513ba4-9de7-4875-801c-5ae69439fe77', '014c4da5-d493-4074-96de-b39782b99fd6', 'numeric', 'Zara and Ivy share 14 marbles in the ratio 4 : 3. How many marbles does Ivy get?', null, '{"value":"6"}'::jsonb, null, 'There are 4 + 3 = 7 parts. Each part is 14 ÷ 7 = 2. Ivy gets 3 parts: 3 × 2 = 6.', 'Add the ratio numbers to find the total number of parts.', 3, 10, 2, true),
  ('b051405d-9ae7-43bc-bf1c-5953953a000a', '014c4da5-d493-4074-96de-b39782b99fd6', 'multiple_choice', 'What is the ratio of fish to apples, in its simplest form?', '{"kind":"ratio","a":{"object":"fish","count":4},"b":{"object":"apple","count":6}}'::jsonb, '{"value":"b"}'::jsonb, '[{"id":"a","label":"3 : 2"},{"id":"b","label":"2 : 3"},{"id":"c","label":"4 : 10"},{"id":"d","label":"3 : 6"}]'::jsonb, 'There are 4 fish and 6 apples, so the ratio is 4 : 6. Divide both numbers by 2: 4 ÷ 2 = 2 and 6 ÷ 2 = 3. The ratio is 2 : 3.', 'Find a number that divides both counts exactly.', 3, 10, 3, true),
  ('af513eca-9be7-454f-be1c-57c0963a019d', '014c4da5-d493-4074-96de-b39782b99fd6', 'numeric', 'Ben and Leo share 16 marbles in the ratio 3 : 5. How many marbles does Leo get?', null, '{"value":"10"}'::jsonb, null, 'There are 3 + 5 = 8 parts. Each part is 16 ÷ 8 = 2. Leo gets 5 parts: 5 × 2 = 10.', 'Add the ratio numbers to find the total number of parts.', 3, 10, 4, true),
  ('aa5136eb-98e7-4096-851c-62c58f39f698', '014c4da5-d493-4074-96de-b39782b99fd6', 'numeric', 'Mia and Leo share 56 marbles in the ratio 3 : 4. How many marbles does Leo get?', null, '{"value":"32"}'::jsonb, null, 'There are 3 + 4 = 7 parts. Each part is 56 ÷ 7 = 8. Leo gets 4 parts: 4 × 8 = 32.', 'Add the ratio numbers to find the total number of parts.', 3, 10, 5, true),
  ('5283b206-1527-4bad-9885-4bd875622cc7', 'e922268c-0682-478b-9d81-68ae70200c8d', 'compare', 'Which sign makes this true?', '{"kind":"compare","left":"4","right":"-4"}'::jsonb, '{"value":">"}'::jsonb, null, 'On a number line, numbers get bigger as you go right. 4 is to the right of −4, so 4 is greater. That means 4 > −4.', 'Picture a number line. Which number is further right?', 1, 10, 1, true),
  ('5383b399-1427-4a1a-9985-4d6b74622b34', 'e922268c-0682-478b-9d81-68ae70200c8d', 'multiple_choice', 'Which number is the smallest?', null, '{"value":"b"}'::jsonb, '[{"id":"a","label":"-5"},{"id":"b","label":"-14"},{"id":"c","label":"-11"},{"id":"d","label":"9"}]'::jsonb, 'In order from smallest to biggest: -14, -11, -5, 9. The smallest is -14.', 'Put the numbers in order first.', 1, 10, 2, true),
  ('5083aee0-1327-4887-9a85-4efe77622fed', 'e922268c-0682-478b-9d81-68ae70200c8d', 'compare', 'Which sign makes this true?', '{"kind":"compare","left":"5","right":"-9"}'::jsonb, '{"value":">"}'::jsonb, null, 'On a number line, numbers get bigger as you go right. 5 is to the right of −9, so 5 is greater. That means 5 > −9.', 'Picture a number line. Which number is further right?', 1, 10, 3, true),
  ('5183b073-1227-46f4-9b85-509176622e5a', 'e922268c-0682-478b-9d81-68ae70200c8d', 'multiple_choice', 'Which number is the biggest?', null, '{"value":"b"}'::jsonb, '[{"id":"a","label":"-4"},{"id":"b","label":"5"},{"id":"c","label":"-7"},{"id":"d","label":"-11"}]'::jsonb, 'In order from smallest to biggest: -11, -7, -4, 5. The biggest is 5.', 'Put the numbers in order first.', 1, 10, 4, true),
  ('5683b852-1127-4561-9c85-52247162267b', 'e922268c-0682-478b-9d81-68ae70200c8d', 'compare', 'Which sign makes this true?', '{"kind":"compare","left":"2","right":"-8"}'::jsonb, '{"value":">"}'::jsonb, null, 'On a number line, numbers get bigger as you go right. 2 is to the right of −8, so 2 is greater. That means 2 > −8.', 'Picture a number line. Which number is further right?', 1, 10, 5, true),
  ('6c820e24-b74c-49ad-8785-74aadc866f83', 'c7b1bd5e-f206-4953-afd2-8a840eb9c009', 'numeric', 'What is −10 − 3?', '{"kind":"number_line","min":-14,"max":-9,"step":1,"highlight":[-10],"jumps":[{"from":-10,"to":-13}]}'::jsonb, '{"value":"-13"}'::jsonb, null, 'Start at −10 on the number line. Subtracting 3 means moving 3 to the left. You land on −13, so −10 − 3 = −13.', 'Adding moves right, subtracting moves left.', 2, 10, 1, true),
  ('6d820fb7-b64c-481a-8885-763ddb866df0', 'c7b1bd5e-f206-4953-afd2-8a840eb9c009', 'numeric', 'What is 4 − 9?', '{"kind":"number_line","min":-6,"max":5,"step":1,"highlight":[4],"jumps":[{"from":4,"to":-5}]}'::jsonb, '{"value":"-5"}'::jsonb, null, 'Start at 4 on the number line. Subtracting 9 means moving 9 to the left. You land on −5, so 4 − 9 = −5.', 'Adding moves right, subtracting moves left.', 2, 10, 2, true),
  ('6e82114a-b54c-4687-8585-7184de8672a9', 'c7b1bd5e-f206-4953-afd2-8a840eb9c009', 'numeric', 'What is 1 − (−8)?', null, '{"value":"9"}'::jsonb, null, 'Subtracting a negative number is the same as adding the positive number. 1 − (−8) = 1 + 8 = 9.', 'Two minus signs together make a plus.', 2, 10, 3, true),
  ('6f8212dd-b44c-44f4-8685-7317dd867116', 'c7b1bd5e-f206-4953-afd2-8a840eb9c009', 'numeric', 'What is −8 − 9?', '{"kind":"number_line","min":-18,"max":-7,"step":1,"highlight":[-8],"jumps":[{"from":-8,"to":-17}]}'::jsonb, '{"value":"-17"}'::jsonb, null, 'Start at −8 on the number line. Subtracting 9 means moving 9 to the left. You land on −17, so −8 − 9 = −17.', 'Adding moves right, subtracting moves left.', 2, 10, 4, true),
  ('688207d8-b34c-4361-8385-6e5ee08675cf', 'c7b1bd5e-f206-4953-afd2-8a840eb9c009', 'numeric', 'What is 6 − (−1)?', null, '{"value":"7"}'::jsonb, null, 'Subtracting a negative number is the same as adding the positive number. 6 − (−1) = 6 + 1 = 7.', 'Two minus signs together make a plus.', 2, 10, 5, true),
  ('90276017-8bcf-4a78-a994-c2c9fe5a509a', '684bf745-e1dd-47ae-9dd8-a6f712cb4d48', 'numeric', 'At noon it was 7°C. At midnight it was −10°C. How many degrees colder was it at midnight?', '{"kind":"thermometer","value":-10}'::jsonb, '{"value":"17"}'::jsonb, null, 'From −10°C up to 0°C is 10 degrees, and from 0°C up to 7°C is 7 degrees. 10 + 7 = 17 degrees.', 'Count up to 0 first, then on to the warmer temperature.', 3, 10, 1, true),
  ('8f275e84-8ccf-4c0b-a894-c136ff5a522d', '684bf745-e1dd-47ae-9dd8-a6f712cb4d48', 'numeric', 'The temperature is 4°C. It rises by 8 degrees. What is the temperature now, in °C?', '{"kind":"thermometer","value":4}'::jsonb, '{"value":"12"}'::jsonb, null, 'Rising means add: 4 + 8 = 12. The temperature is now 12°C.', 'Count up the thermometer.', 3, 10, 2, true),
  ('9227633d-8dcf-4d9e-a794-bfa3fc5a4d74', '684bf745-e1dd-47ae-9dd8-a6f712cb4d48', 'numeric', 'At noon it was 3°C. At midnight it was −9°C. How many degrees colder was it at midnight?', '{"kind":"thermometer","value":-9}'::jsonb, '{"value":"12"}'::jsonb, null, 'From −9°C up to 0°C is 9 degrees, and from 0°C up to 3°C is 3 degrees. 9 + 3 = 12 degrees.', 'Count up to 0 first, then on to the warmer temperature.', 3, 10, 3, true),
  ('912761aa-8ecf-4f31-a694-be10fd5a4f07', '684bf745-e1dd-47ae-9dd8-a6f712cb4d48', 'numeric', 'The temperature is 1°C. It falls by 12 degrees. What is the temperature now, in °C?', '{"kind":"thermometer","value":1}'::jsonb, '{"value":"-11"}'::jsonb, null, 'Falling means subtract: 1 − 12 = −11. The temperature is now −11°C.', 'Count down the thermometer. You may go below zero.', 3, 10, 4, true),
  ('8c2759cb-8fd0-40c4-ad94-c915fa5a4a4e', '684bf745-e1dd-47ae-9dd8-a6f712cb4d48', 'numeric', 'The temperature is 0°C. It falls by 8 degrees. What is the temperature now, in °C?', '{"kind":"thermometer","value":0}'::jsonb, '{"value":"-8"}'::jsonb, null, 'Falling means subtract: 0 − 8 = −8. The temperature is now −8°C.', 'Count down the thermometer. You may go below zero.', 3, 10, 5, true),
  ('1a9f0d6e-3b77-4321-926b-3d386c657c93', 'f60ed9e4-4a14-412f-861e-d27eb1b3f6a9', 'numeric', 'What is the perimeter of a rectangle 14 cm long and 13 cm wide?', '{"kind":"rectangle","width":14,"height":13,"unit":"cm"}'::jsonb, '{"value":"54"}'::jsonb, null, 'Perimeter is the distance all the way around. Add all four sides: 14 + 13 + 14 + 13 = 54 cm. That is the same as 2 × (14 + 13).', 'A rectangle has two long sides and two short sides.', 1, 10, 1, true),
  ('1b9f0f01-3a77-418e-936b-3ecb6b657b00', 'f60ed9e4-4a14-412f-861e-d27eb1b3f6a9', 'numeric', 'What is the perimeter of a rectangle 11 cm long and 5 cm wide?', '{"kind":"rectangle","width":11,"height":5,"unit":"cm"}'::jsonb, '{"value":"32"}'::jsonb, null, 'Perimeter is the distance all the way around. Add all four sides: 11 + 5 + 11 + 5 = 32 cm. That is the same as 2 × (11 + 5).', 'A rectangle has two long sides and two short sides.', 1, 10, 2, true),
  ('189f0a48-3977-4ffb-946b-405e6e657fb9', 'f60ed9e4-4a14-412f-861e-d27eb1b3f6a9', 'numeric', 'A square has a perimeter of 36 cm. How long is each side, in cm?', null, '{"value":"9"}'::jsonb, null, 'A square has 4 equal sides, so divide the perimeter by 4: 36 ÷ 4 = 9. Each side is 9 cm.', 'A square has 4 sides that are all the same length.', 1, 10, 3, true),
  ('199f0bdb-3877-4e68-956b-41f16d657e26', 'f60ed9e4-4a14-412f-861e-d27eb1b3f6a9', 'numeric', 'What is the perimeter of a rectangle 17 m long and 20 m wide?', '{"kind":"rectangle","width":17,"height":20,"unit":"m"}'::jsonb, '{"value":"74"}'::jsonb, null, 'Perimeter is the distance all the way around. Add all four sides: 17 + 20 + 17 + 20 = 74 m. That is the same as 2 × (17 + 20).', 'A rectangle has two long sides and two short sides.', 1, 10, 4, true),
  ('1e9f13ba-3f77-496d-966b-4384706582df', 'f60ed9e4-4a14-412f-861e-d27eb1b3f6a9', 'numeric', 'What is the perimeter of a rectangle 7 cm long and 2 cm wide?', '{"kind":"rectangle","width":7,"height":2,"unit":"cm"}'::jsonb, '{"value":"18"}'::jsonb, null, 'Perimeter is the distance all the way around. Add all four sides: 7 + 2 + 7 + 2 = 18 cm. That is the same as 2 × (7 + 2).', 'A rectangle has two long sides and two short sides.', 1, 10, 5, true),
  ('d536603b-a0b4-424c-96b1-4cbd1f8395de', '111e6d59-4819-412a-8d07-1f638046fd2c', 'numeric', 'What is the area of a rectangle 3 cm long and 7 cm wide, in cm²?', '{"kind":"rectangle","width":3,"height":7,"unit":"cm","showGrid":true}'::jsonb, '{"value":"21"}'::jsonb, null, 'Area = length × width. 3 × 7 = 21, so the area is 21 cm². That is 7 rows of 3 squares.', 'Multiply the length by the width.', 2, 10, 1, true),
  ('d4365ea8-a1b4-43df-95b1-4b2a20839771', '111e6d59-4819-412a-8d07-1f638046fd2c', 'numeric', 'What is the area of a rectangle 7 cm long and 6 cm wide, in cm²?', '{"kind":"rectangle","width":7,"height":6,"unit":"cm","showGrid":true}'::jsonb, '{"value":"42"}'::jsonb, null, 'Area = length × width. 7 × 6 = 42, so the area is 42 cm². That is 6 rows of 7 squares.', 'Multiply the length by the width.', 2, 10, 2, true),
  ('d7366361-a2b4-4572-94b1-49971d8392b8', '111e6d59-4819-412a-8d07-1f638046fd2c', 'numeric', 'What is the area of a rectangle 6 cm long and 5 cm wide, in cm²?', '{"kind":"rectangle","width":6,"height":5,"unit":"cm","showGrid":false}'::jsonb, '{"value":"30"}'::jsonb, null, 'Area = length × width. 6 × 5 = 30, so the area is 30 cm².', 'Multiply the length by the width.', 2, 10, 3, true),
  ('d63661ce-a3b4-4705-93b1-48041e83944b', '111e6d59-4819-412a-8d07-1f638046fd2c', 'numeric', 'A rectangle has an area of 45 cm² and a width of 5 cm. How long is it, in cm?', null, '{"value":"9"}'::jsonb, null, 'Area = length × width, so length = area ÷ width. 45 ÷ 5 = 9 cm. Check: 9 × 5 = 45.', 'Which number times 5 makes 45?', 2, 10, 4, true),
  ('d9366687-9cb4-4c00-92b1-467123839c2a', '111e6d59-4819-412a-8d07-1f638046fd2c', 'numeric', 'What is the area of a rectangle 8 cm long and 8 cm wide, in cm²?', '{"kind":"rectangle","width":8,"height":8,"unit":"cm","showGrid":false}'::jsonb, '{"value":"64"}'::jsonb, null, 'Area = length × width. 8 × 8 = 64, so the area is 64 cm².', 'Multiply the length by the width.', 2, 10, 5, true),
  ('9035d116-0efb-4c4b-ae4d-a670bf68684d', '8744379c-ed0a-436d-bfb0-dfce89ad5c57', 'numeric', 'A triangle has a base of 10 cm and a height of 11 cm. What is its area, in cm²?', '{"kind":"triangle","base":10,"height":11,"unit":"cm"}'::jsonb, '{"value":"55"}'::jsonb, null, 'A triangle is half of a rectangle with the same base and height. Area = 1/2 × base × height = 1/2 × 10 × 11 = 55 cm².', 'Find base × height, then halve it.', 3, 10, 1, true),
  ('9135d2a9-0dfb-4ab8-af4d-a803be6866ba', '8744379c-ed0a-436d-bfb0-dfce89ad5c57', 'numeric', 'A triangle has a base of 12 cm and a height of 10 cm. What is its area, in cm²?', '{"kind":"triangle","base":12,"height":10,"unit":"cm"}'::jsonb, '{"value":"60"}'::jsonb, null, 'A triangle is half of a rectangle with the same base and height. Area = 1/2 × base × height = 1/2 × 12 × 10 = 60 cm².', 'Find base × height, then halve it.', 3, 10, 2, true),
  ('8e35cdf0-10fb-4f71-b04d-a996bd686527', '8744379c-ed0a-436d-bfb0-dfce89ad5c57', 'numeric', 'A rectangle has an area of 25 cm² and a width of 5 cm. How long is it, in cm?', null, '{"value":"5"}'::jsonb, null, 'Area = length × width, so length = area ÷ width. 25 ÷ 5 = 5 cm. Check: 5 × 5 = 25.', 'Which number times 5 makes 25?', 3, 10, 3, true),
  ('8f35cf83-0ffb-4dde-b14d-ab29bc686394', '8744379c-ed0a-436d-bfb0-dfce89ad5c57', 'numeric', 'A garden is 10 m long and 6 m wide. What is its area, in m²?', '{"kind":"rectangle","width":10,"height":6,"unit":"m"}'::jsonb, '{"value":"60"}'::jsonb, null, 'Area = length × width = 10 × 6 = 60. The garden has an area of 60 m².', 'Multiply the length by the width.', 3, 10, 4, true),
  ('9435d762-12fb-4297-b24d-acbcbb686201', '8744379c-ed0a-436d-bfb0-dfce89ad5c57', 'numeric', 'A triangle has a base of 14 cm and a height of 4 cm. What is its area, in cm²?', '{"kind":"triangle","base":14,"height":4,"unit":"cm"}'::jsonb, '{"value":"28"}'::jsonb, null, 'A triangle is half of a rectangle with the same base and height. Area = 1/2 × base × height = 1/2 × 14 × 4 = 28 cm².', 'Find base × height, then halve it.', 3, 10, 5, true),
  ('ecc91ff2-28b2-4f29-aea1-d1acc8f72243', '327c2d58-9405-4fbf-aada-190aa131e319', 'numeric', 'If n = 6, what is 3n − 7?', null, '{"value":"11"}'::jsonb, null, '3n means 3 × n. Replace n with 6: 3 × 6 = 18. Then 18 − 7 = 11.', '3n means 3 times n.', 1, 10, 1, true),
  ('edc92185-27b2-4d96-afa1-d33fc7f720b0', '327c2d58-9405-4fbf-aada-190aa131e319', 'numeric', 'If n = 8, what is 3n + 2?', null, '{"value":"26"}'::jsonb, null, '3n means 3 × n. Replace n with 8: 3 × 8 = 24. Then 24 + 2 = 26.', '3n means 3 times n.', 1, 10, 2, true),
  ('eac91ccc-26b2-4c03-b0a1-d4d2caf72569', '327c2d58-9405-4fbf-aada-190aa131e319', 'multiple_choice', 'Which expression means "multiply a number n by 4, then add 3"?', null, '{"value":"c"}'::jsonb, '[{"id":"a","label":"4 + 3n"},{"id":"b","label":"n + 4 + 3"},{"id":"c","label":"4n + 3"},{"id":"d","label":"3n + 4"}]'::jsonb, 'Multiplying n by 4 gives 4n. Adding 3 gives 4n + 3.', 'Write the multiplying part first.', 1, 10, 3, true),
  ('ebc91e5f-25b2-4a70-b1a1-d665c9f723d6', '327c2d58-9405-4fbf-aada-190aa131e319', 'numeric', 'If n = 5, what is 5n + 7?', null, '{"value":"32"}'::jsonb, null, '5n means 5 × n. Replace n with 5: 5 × 5 = 25. Then 25 + 7 = 32.', '5n means 5 times n.', 1, 10, 4, true),
  ('e8c919a6-2cb2-4575-aaa1-cb60ccf7288f', '327c2d58-9405-4fbf-aada-190aa131e319', 'numeric', 'If n = 9, what is 2n + 6?', null, '{"value":"24"}'::jsonb, null, '2n means 2 × n. Replace n with 9: 2 × 9 = 18. Then 18 + 6 = 24.', '2n means 2 times n.', 1, 10, 5, true),
  ('0ef8322b-20e1-426c-b864-3a451a2d35fe', 'ee175789-43e1-4c82-918a-4b0346c8d77c', 'numeric', 'Solve: 6x = 72. What is x?', null, '{"value":"12"}'::jsonb, null, '6x means 6 × x. Divide both sides by 6: x = 72 ÷ 6 = 12. Check: 6 × 12 = 72.', 'Do the opposite of multiplying.', 2, 10, 1, true),
  ('0df83098-21e1-43ff-b764-38b21b2d3791', 'ee175789-43e1-4c82-918a-4b0346c8d77c', 'numeric', 'Solve: 7x = 77. What is x?', null, '{"value":"11"}'::jsonb, null, '7x means 7 × x. Divide both sides by 7: x = 77 ÷ 7 = 11. Check: 7 × 11 = 77.', 'Do the opposite of multiplying.', 2, 10, 2, true),
  ('10f83551-22e1-4592-b664-371f182d32d8', 'ee175789-43e1-4c82-918a-4b0346c8d77c', 'numeric', 'Solve: 3x + 5 = 38. What is x?', null, '{"value":"11"}'::jsonb, null, 'First subtract 5 from both sides: 3x = 38 − 5 = 33. Then divide both sides by 3: x = 33 ÷ 3 = 11. Check: 3 × 11 + 5 = 38.', 'Undo the + 5 first, then undo the × 3.', 2, 10, 3, true),
  ('0ff833be-23e1-4725-b564-358c192d346b', 'ee175789-43e1-4c82-918a-4b0346c8d77c', 'numeric', 'Solve: x + 8 = 16. What is x?', null, '{"value":"8"}'::jsonb, null, 'Subtract 8 from both sides to get x on its own: x = 16 − 8 = 8. Check: 8 + 8 = 16.', 'Do the opposite of adding.', 2, 10, 4, true),
  ('12f83877-1ce1-4c20-b464-33f91e2d3c4a', 'ee175789-43e1-4c82-918a-4b0346c8d77c', 'numeric', 'Solve: 6x + 1 = 43. What is x?', null, '{"value":"7"}'::jsonb, null, 'First subtract 1 from both sides: 6x = 43 − 1 = 42. Then divide both sides by 6: x = 42 ÷ 6 = 7. Check: 6 × 7 + 1 = 43.', 'Undo the + 1 first, then undo the × 6.', 2, 10, 5, true),
  ('03c00f25-1af6-4288-8651-dd1ff6180c9a', 'a71c0567-02dd-4d66-8368-3db11a369328', 'numeric', 'Tickets cost $4 each. Kai buys 3 tickets and pays with $20. How many dollars of change does Kai get?', null, '{"value":"8"}'::jsonb, null, 'Step 1: total cost = 3 × $4 = $12. Step 2: change = $20 − $12 = $8.', 'First find the total cost of the tickets.', 3, 10, 1, true),
  ('02c00d92-1bf6-441b-8551-db8cf7180e2d', 'a71c0567-02dd-4d66-8368-3db11a369328', 'numeric', 'Lily saves $8 every week for 5 weeks, then spends $34 on a book. How many dollars does Lily have left?', null, '{"value":"6"}'::jsonb, null, 'Step 1: savings = 5 × $8 = $40. Step 2: after buying the book, $40 − $34 = $6.', 'First find how much was saved altogether.', 3, 10, 2, true),
  ('01c00bff-1cf6-45ae-8851-e045f4180974', 'a71c0567-02dd-4d66-8368-3db11a369328', 'numeric', 'Ava saves $3 every week for 7 weeks, then spends $12 on a book. How many dollars does Ava have left?', null, '{"value":"9"}'::jsonb, null, 'Step 1: savings = 7 × $3 = $21. Step 2: after buying the book, $21 − $12 = $9.', 'First find how much was saved altogether.', 3, 10, 3, true),
  ('00c00a6c-1df6-4741-8751-deb2f5180b07', 'a71c0567-02dd-4d66-8368-3db11a369328', 'numeric', 'Noah saves $8 every week for 5 weeks, then spends $37 on a book. How many dollars does Noah have left?', null, '{"value":"3"}'::jsonb, null, 'Step 1: savings = 5 × $8 = $40. Step 2: after buying the book, $40 − $37 = $3.', 'First find how much was saved altogether.', 3, 10, 4, true),
  ('ffc008d9-1ef6-48d4-8251-d6d3f218064e', 'a71c0567-02dd-4d66-8368-3db11a369328', 'numeric', 'Tickets cost $8 each. Zara buys 5 tickets and pays with $50. How many dollars of change does Zara get?', null, '{"value":"10"}'::jsonb, null, 'Step 1: total cost = 5 × $8 = $40. Step 2: change = $50 − $40 = $10.', 'First find the total cost of the tickets.', 3, 10, 5, true)
